output_text:
[
  {
    "id": "single_file_aisles_cart_free",
    "text": "Shopping carts are prohibited in single-file shelf aisles.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            "adjShelf",
            "shelfE",
            "shelfW",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "singleFileShelfAisle"
        ]
      }
    }
  },
  {
    "id": "no_cart_entry_to_single_file",
    "text": "Customers must park the cart before moving into a single-file shelf aisle.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            "adjShelf",
            "shelfE",
            "shelfW",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {
        "enterSingleFileWithCart": {
          "pre": {
            "and": [
              "hasCart",
              "MOVE"
            ]
          },
          "post": "singleFileShelfAisle"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "enterSingleFileWithCart"
    }
  },
  {
    "id": "cartless_shelf_only_in_single_file",
    "text": "Shelf interactions without a cart are allowed only inside pedestrian-only single-file aisles.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            "adjShelf",
            "shelfE",
            "shelfW",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "INTERACT",
          "adjShelf",
          {
            "not": "hasCart"
          },
          {
            "not": "singleFileShelfAisle"
          }
        ]
      }
    }
  },
  {
    "id": "drop_cart_only_at_mouths",
    "text": "Customers may set down a cart only at the entrance cart station or at the mouth of a pedestrian-only aisle.",
    "abstraction": {
      "state_properties": {
        "cartStation": "at(1,7)",
        "pedestrianAisleMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        },
        "approvedCartSetDownPoint": {
          "or": [
            "cartStation",
            "pedestrianAisleMouth"
          ]
        }
      },
      "events": {
        "setDownCart": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "setDownCart",
          {
            "not": "approvedCartSetDownPoint"
          }
        ]
      }
    }
  },
  {
    "id": "retrieve_cart_after_pedestrian_aisle",
    "text": "After entering a pedestrian-only shelf aisle without a cart, the customer is obliged to retrieve a cart before leaving the store.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            "adjShelf",
            "shelfE",
            "shelfW",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {
        "cartlessInSingleFileAisle": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "singleFileShelfAisle"
            ]
          },
          "post": null
        },
        "retrieveCart": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "cartlessInSingleFileAisle",
      "discharge": "retrieveCart"
    }
  },
  {
    "id": "no_cartless_cruising_main_aisles",
    "text": "Away from the entrance and pedestrian-only aisles, customers should not move through the main store without a cart.",
    "abstraction": {
      "state_properties": {
        "entryApron": {
          "or": [
            "at(0,7)",
            "at(1,7)"
          ]
        },
        "singleFileShelfAisle": {
          "and": [
            "adjShelf",
            "shelfE",
            "shelfW",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        },
        "mainCustomerAisle": {
          "and": [
            {
              "not": "entryApron"
            },
            {
              "not": "singleFileShelfAisle"
            }
          ]
        }
      },
      "events": {
        "cartlessMainToMainMove": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "MOVE",
              "mainCustomerAisle"
            ]
          },
          "post": "mainCustomerAisle"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "cartlessMainToMainMove"
    }
  },
  {
    "id": "interact_only_at_service_points",
    "text": "Interactions are permitted only at recognized service points: the cart station, cart-parking aisle mouths, or adjacent shelves.",
    "abstraction": {
      "state_properties": {
        "cartStation": "at(1,7)",
        "pedestrianAisleMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        },
        "shelfServicePoint": "adjShelf",
        "servicePoint": {
          "or": [
            "cartStation",
            "pedestrianAisleMouth",
            "shelfServicePoint"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "INTERACT",
          {
            "not": "servicePoint"
          }
        ]
      }
    }
  },
  {
    "id": "single_file_entry_requires_shopping",
    "text": "A customer who enters a single-file pedestrian shelf aisle without a cart must perform a shelf interaction there.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            "adjShelf",
            "shelfE",
            "shelfW",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {
        "enterSingleFileWithoutCart": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "MOVE",
              {
                "not": "singleFileShelfAisle"
              }
            ]
          },
          "post": "singleFileShelfAisle"
        },
        "handShopInSingleFile": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "INTERACT",
              "singleFileShelfAisle"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "enterSingleFileWithoutCart",
      "discharge": "handShopInSingleFile"
    }
  }
]
